// #86e6bc «תאריכים חשובים» на главной — עבר QA 19.11.2026 (iPhone и Android; подтвердил пользователь).
//   Факт: кнопка «+» (accessibility label «הוספת תאריך חשוב») — в строке заголовка «תאריכים חשובים», а не внизу списка; в свёрнутом виде видны
//   только даты ближайших 14 дней (вкл. сегодня), от ближней к дальней, прошедшие скрыты; если в 2 недели ничего нет — «אין תאריכים חשובים בשבועיים הקרובים.»;
//   «להראות הכל» раскрывает все → кнопка «להסתיר הכל» → сворачивает; кнопка видна только когда есть скрытые.
//   Здесь — проверки без создания данных (@prod-safe, меняется только развёрнутость списка). Создание дат +5/+13/+16 — q-37.
//   Кейс: .qa/tests/phone/qa-2026-11-19.md (Q19-03a). «Прошедшие скрыты / порядок по датам» на чужих данных аккаунта — глазами (@manual-check в q-37).
import { expect } from '@wdio/globals';
import { toHome } from '../../helpers/app.ts';
import { byLabel, byTextContains } from '../../helpers/ui.ts';
import { rectOf } from '../_lib/app-1310.ts';
import { shown } from '../_lib/app-0710.ts';
import {
  IMPORTANT, ADD_LABEL, SHOW_ALL, HIDE_ALL, EMPTY_TWO_WEEKS,
  homeDatesHeading, ensureCollapsed, expandAll, dateCardLabels, toggleShown, findToggle, saveShot,
} from '../_lib/app-1911.ts';

describe('19.11 — «תאריכים חשובים» на главной: «+» в шапке, свёрнутый список, «להראות הכל» (#86e6bc)', () => {
  afterEach(async () => { await toHome(); });

  it('Q19-03a «+» «הוספת תאריך חשוב» — в строке заголовка «תאריכים חשובים», выше списка; свёрнутый вид: нет карточек ⇔ «אין תאריכים חשובים בשבועיים הקרובים.» #86e6bc @prod-safe', async () => {
    const wasExpanded = await ensureCollapsed();
    console.log(`[Q-36] список был ${wasExpanded ? 'развёрнут (свернули)' : 'свёрнут'}`);

    // 1. «+» в строке заголовка: по вертикали рядом с «תאריכים חשובים» (не больше полутора высот кнопки), и выше первой карточки.
    const heading = await homeDatesHeading();
    const add = await byLabel(ADD_LABEL);
    await add.waitForDisplayed({ timeout: 15000 });
    const a = await rectOf(add);
    const headCy = heading.y + heading.h / 2;
    const addCy = a.y + a.height / 2;
    console.log(`[Q-36] «${IMPORTANT}» cy=${headCy}, «+» cy=${addCy}, высота кнопки ${a.height}`);
    expect(Math.abs(addCy - headCy)).toBeLessThanOrEqual(Math.max(a.height, heading.h) * 1.5);
    await saveShot('q36-header-plus.png');

    // 2. Свёрнутый вид: карточки (если есть) — все выше переключателя; пусто ⇔ есть текст про две недели.
    const cards = await dateCardLabels();
    console.log(`[Q-36] карточек в свёрнутом виде: ${cards.length}`);
    await homeDatesHeading();
    const emptyShown = await shown(byTextContains(EMPTY_TWO_WEEKS));
    if (cards.length === 0) expect(emptyShown).toBe(true);
    else expect(emptyShown).toBe(false);
  });

  it('Q19-03b «להראות הכל» раскрывает (карточек больше) → «להסתיר הכל» сворачивает обратно; без скрытых дат кнопки нет #86e6bc @prod-safe', async () => {
    await ensureCollapsed();
    const before = await dateCardLabels();
    await homeDatesHeading();
    const hasShow = (await findToggle(SHOW_ALL, 10)) !== null;
    console.log(`[Q-36] «${SHOW_ALL}»: ${hasShow ? 'есть' : 'нет'}; карточек ${before.length}`);

    if (!hasShow) {
      // Скрытых дат нет → ни одной из кнопок на экране.
      expect(await toggleShown(HIDE_ALL)).toBe(false);
      console.log('[Q-36] скрытых дат у аккаунта нет — раскрытие проверяет q-37 (дата +16)');
      return;
    }
    expect(await expandAll()).toBe(true);
    const expanded = await dateCardLabels();
    expect(expanded.length).toBeGreaterThan(before.length);
    for (const l of before) expect(expanded).toContain(l);       // ближайшие остались
    await saveShot('q36-expanded.png');

    // «להסתיר הכל» → снова свёрнуто: столько же карточек, кнопка «להראות הכל».
    await homeDatesHeading();
    const hide = await findToggle(HIDE_ALL, 10);
    expect(hide).not.toBeNull();
    await hide!.click();
    const after = await dateCardLabels();
    expect(after.length).toBe(before.length);
    await homeDatesHeading();
    expect(await findToggle(SHOW_ALL, 10)).not.toBeNull();
  });
});
